import hashlib

TARGET_HASH = 'a60458d2180258d47d7f7bef5236b33e86711ac926518ca4545ebf24cdc0b76c'
SALT = 'sha256'

def try_hash(input_str):
    result = hashlib.sha256((SALT + input_str).encode()).hexdigest()
    if result == TARGET_HASH:
        print(f"Found match! Input: {input_str}")
        print(f"Hash: {result}")
        return True
    return False

