    for w2 in base_words:
        if w1 != w2:
            combinations = [
                f"{w1}{w2}",
                f"{w1}_{w2}",
                f"{w1.capitalize()}{w2}",
                f"{w1.upper()}_{w2.upper()}"
            ]
            for combo in combinations:
